rency=b.currency AND date(f.business_date)<=date(b.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_num,(SELECT f.fx_den FROM active f WHERE f.kind='fx' AND f.currency=b.currency AND date(f.business_date)<=date(b.business_date) ORDER BY date(f.business_date) DESC LIMIT 1) AS fx_den FROM balances b) SELECT SUM(CAST(ROUND(MAX(0,remaining-holds)*CASE WHEN date(discount_until)>=date('2026-10-23') THEN (10000-discount_bps) ELSE 10000 END*fx_num*1.0/(10000*fx_den)) AS INTEGER)) AS usd_cents FROM priced WHERE fx_den>0\"}}"}}
